-- Run AFTER cms-insights-delegation.sql. All fixtures and temporary role changes roll back.
begin;
select set_config('cms.qa.admin',(select id::text from auth.users where lower(email)='taran.dhillon@devanhaar.com'),true);
select set_config('cms.qa.editor',(select id::text from auth.users where lower(email)='amritpal.singh@devanhaar.com'),true);
update public.admin_profiles set role='content_manager' where id=current_setting('cms.qa.editor')::uuid;
select set_config('request.jwt.claim.sub',current_setting('cms.qa.admin'),true);
set local role authenticated;
do $check$
declare project_a uuid;project_b uuid;article uuid;foreign_article uuid;rev uuid;foreign_rev uuid;stamp timestamptz;v public.cms_entries%rowtype;project_body jsonb;body jsonb;other_body jsonb;restored jsonb;denied boolean;prefix text:='qa-delegation-'||substr(gen_random_uuid()::text,1,8);
begin
 select r.body into project_body from public.cms_entries e join public.cms_entry_revisions r on r.id=e.published_revision_id where e.kind='project' limit 1;
 if project_body is null then raise exception 'A published project is required for this verification';end if;
 project_a:=public.cms_write_entry('project',prefix||'-a',project_body,null,null,null,'save');
 project_b:=public.cms_write_entry('project',prefix||'-b',project_body,null,null,null,'save');
 perform public.cms_assign_entry(project_a,current_setting('cms.qa.editor')::uuid,true,true,true,false);
 body:=jsonb_build_object('title','Delegation verification','excerpt','Test','content','Private draft','pillar','Develop','tags','[]'::jsonb,'published_at','2026-10-27T12:00:00Z','cms_metadata',jsonb_build_object('projectId',project_a,'subtitle','','category','','seoTitle','','seoDescription','','socialTitle','','socialDescription','','socialImage','','noIndex',true,'featured',false,'relatedLinks','[]'::jsonb));
 other_body:=jsonb_set(body,'{cms_metadata,projectId}',to_jsonb(project_b));
 foreign_article:=public.blog_write_revision(prefix||'-foreign',other_body,null,null,false);
 select draft_revision_id into foreign_rev from public.blog_posts where id=foreign_article;
 perform set_config('request.jwt.claim.sub',current_setting('cms.qa.editor'),true);
 if exists(select 1 from public.blog_posts where id=foreign_article)then raise exception 'Unassigned draft leaked';end if;
 article:=public.blog_write_revision(prefix||'-own',body,null,null,false);
 select draft_revision_id,updated_at into rev,stamp from public.blog_posts where id=article;
 denied:=false;begin perform public.blog_write_revision(prefix||'-own',body,rev,stamp,true);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Editor published without Publish permission';end if;
 denied:=false;begin perform public.blog_write_revision(prefix||'-outside',other_body,null,null,false);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Editor created an unassigned project article';end if;
 denied:=false;begin perform public.blog_restore_revision(prefix||'-own',foreign_rev,rev,stamp);exception when invalid_parameter_value then denied:=true;end;
 if not denied then raise exception 'Foreign article revision was accepted';end if;
 perform set_config('request.jwt.claim.sub',current_setting('cms.qa.admin'),true);
 perform public.cms_assign_entry(project_a,current_setting('cms.qa.editor')::uuid,true,true,true,true);
 perform set_config('request.jwt.claim.sub',current_setting('cms.qa.editor'),true);
 perform public.blog_write_revision(prefix||'-own',body,rev,stamp,true);
 if not exists(select 1 from public.blog_posts where id=article and cms_metadata->>'projectId'=project_a::text and draft_revision_id is null)then raise exception 'Delegated publishing failed';end if;
 select updated_at into stamp from public.blog_posts where id=article;
 perform public.blog_restore_revision(prefix||'-own',rev,null,stamp);
 select draft_revision_id,updated_at into rev,stamp from public.blog_posts where id=article;
 select r.body into restored from public.blog_post_revisions r where r.id=rev;
 perform public.blog_write_revision(prefix||'-own',restored,rev,stamp,true);
 perform set_config('request.jwt.claim.sub',current_setting('cms.qa.admin'),true);
 perform public.cms_assign_entry(project_a,current_setting('cms.qa.editor')::uuid,false,false,false,false);
 perform public.blog_assign_post(article,current_setting('cms.qa.editor')::uuid,true,false,false);
 perform set_config('request.jwt.claim.sub',current_setting('cms.qa.editor'),true);
 if not(public.blog_permissions(prefix||'-own')->>'view')::boolean or(public.blog_permissions(prefix||'-own')->>'edit')::boolean then raise exception 'Exact View-only assignment failed';end if;
 select updated_at into stamp from public.blog_posts where id=article;
 denied:=false;begin perform public.blog_write_revision(prefix||'-own',body,null,stamp,false);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'View-only editor saved a draft';end if;
 if has_table_privilege('authenticated','public.blog_posts','UPDATE') then raise exception 'Direct writes bypass the revision boundary';end if;
 if has_function_privilege('anon','public.blog_assign_post(uuid,uuid,boolean,boolean,boolean)','EXECUTE') then raise exception 'Anonymous assignment access';end if;
end $check$;
rollback;
select count(*) retained_test_articles from public.blog_posts where slug like 'qa-delegation-%';
